<?php namespace App\Filament\Resources\UpbringingEventResource\Pages;use App\Filament\Resources\UpbringingEventResource;use App\Services\PeriodGuard;use Filament\Resources\Pages\CreateRecord;class CreateUpbringingEvent extends CreateRecord{protected static string $resource=UpbringingEventResource::class;protected function mutateFormDataBeforeCreate(array $d):array{$p=request()->attributes->get('academic_period');if($p){PeriodGuard::writable($p->id);$d['academic_period_id']=$p->id;}return $d;}}